"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["12222"],{26932(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>h,frontMatter:()=>r,contentTitle:()=>s,toc:()=>c,assets:()=>l});var i=JSON.parse('{"id":"tianya/bottombodythinking","title":"","description":"\\"The necessary and sufficient condition for a strong nation is military might\\" -- a typical tautology, circular reasoning. A nation\'s true strength must necessarily manifest on the comprehensive level of politics, economy, military power, culture, and so on. Singling out military power alone is the typical lower-body thinking mode of men -- mistaking the part for the whole.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tianya/bottombodythinking.md","sourceDirName":"tianya","slug":"/tianya/bottombodythinking","permalink":"/en/tianya/bottombodythinking","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"bottombodythinking","title":"","hide_table_of_contents":true,"sidebar_label":"\\"Military strength is the necessary and sufficient condition for a strong nation\\" is a product of typical male lower-body thinking"},"sidebar":"tianyaSidebar","previous":{"title":"From the debate on economic models \u2014 online leftists are the basest product of capital\'s identical ignorant reproductive impulse","permalink":"/en/tianya/economicsmodel"},"next":{"title":"CCTV, has the name of China\'s most capable marshal of the last century been erased?","permalink":"/en/tianya/linbiaononame"}}'),o=n(74848),a=n(28453);let r={id:"bottombodythinking",title:"",hide_table_of_contents:!0,sidebar_label:'"Military strength is the necessary and sufficient condition for a strong nation" is a product of typical male lower-body thinking'},s='"The Necessary and Sufficient Condition for a Strong Nation Is Military Might" -- A Typical Product of Men\'s Lower-Body Thinking Mode.',l={},c=[];function d(e){let t={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"the-necessary-and-sufficient-condition-for-a-strong-nation-is-military-might----a-typical-product-of-mens-lower-body-thinking-mode",children:'"The Necessary and Sufficient Condition for a Strong Nation Is Military Might" -- A Typical Product of Men\'s Lower-Body Thinking Mode.'})}),"\n",(0,o.jsx)(t.p,{children:'"The necessary and sufficient condition for a strong nation is military might" -- a typical tautology, circular reasoning. A nation\'s true strength must necessarily manifest on the comprehensive level of politics, economy, military power, culture, and so on. Singling out military power alone is the typical lower-body thinking mode of men -- mistaking the part for the whole.'}),"\n",(0,o.jsx)(t.p,{children:"National strength is a comprehensive metric. No single dimension of politics, economy, military power, or culture alone can serve as the so-called necessary and sufficient condition. Moreover, a nation's stability is also a very important metric. Additionally, particularly important is that national strength is not a constant value -- it is time-dependent. For example, by comprehensive evaluation of politics, economy, military power, and culture, China from the early to middle Qing Dynasty was absolutely a strong nation. Later, national power weakened. So discussing whether the entire Qing Dynasty was a strong nation is meaningless -- it can only be discussed in segments."}),"\n",(0,o.jsx)(t.p,{children:'Of course, we can also use a strengthened definition of "strong nation": if a country has, during a considerable period in its history, ranked in the top three worldwide in political, economic, military, and cultural evaluations, then that country can be called a strong nation. By this definition, there have been very few truly strong nations in world history.'}),"\n",(0,o.jsx)(t.p,{children:"But more importantly, the elements in this comprehensive evaluation system of politics, economy, military power, and culture have some subtle logical relationships. For example, military power from nomadic or maritime cultures easily excels, while other aspects struggle to pass. Conversely, from agrarian or continental cultures, military power is often a mess, while economics and especially culture generally score well. For today's China, the goal should naturally be to become a truly strong nation that ranks in the top three worldwide in politics, economy, military power, and culture -- not a militaristic new Mongol."})]})}function h(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var i=n(96540);let o={},a=i.createContext(o);function r(e){let t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);